import React from 'react';
import Svg, { Path } from 'react-native-svg';
import {
  MARK_BODY,
  MARK_CYAN,
  MARK_LIME,
  MARK_LINES,
  MARK_RAILS,
  MARK_RATIO,
  MARK_VIEWBOX,
} from '../brand/markPaths';

export interface BrandMarkProps {
  /** Rendered height in dp; width follows the mark's ratio. */
  height?: number;
}

/** The Maglev train mark (assets/brand/maglev-mark.svg, generated by scripts/build-logo.py), in its brand colours. */
export function BrandMark({ height = 96 }: BrandMarkProps) {
  return (
    <Svg width={height * MARK_RATIO} height={height} viewBox={MARK_VIEWBOX} accessibilityLabel="Maglev">
      <Path d={MARK_BODY} fill={MARK_LIME} fillRule="evenodd" />
      <Path d={MARK_LINES} fill={MARK_CYAN} />
      <Path d={MARK_RAILS} fill={MARK_CYAN} />
    </Svg>
  );
}
